"""Random inputs for binary search: a count, a sorted array, then a target.

Values are sampled without replacement and then sorted, so the array is always
strictly ascending -- the precondition the problem states. The absent targets
are chosen from outside the sample, so "not there" is a fact about how the
input was built rather than a guess.
"""

LOW, HIGH = -60, 60


def generate(rng, count):
    builders = (_present, _absent_inside, _below_range, _above_range)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, target, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n%d\n" % (len(values),
                                   " ".join(str(v) for v in values), target),
        "description": description,
    }


def _sorted_values(rng):
    return sorted(rng.sample(range(LOW, HIGH), rng.randint(5, 12)))


def _present(rng, index):
    values = _sorted_values(rng)
    position = rng.randrange(len(values))
    where = ("the first element" if position == 0 else
             "the last element" if position == len(values) - 1 else
             "somewhere in the middle")
    return _case("target present #%d" % index, values, values[position],
                 "The target is %s." % where)


def _absent_inside(rng, index):
    # Take twice as many values as the array needs and keep every other one.
    # What is left over sits in the gaps: inside the range, but not present.
    pool = sorted(rng.sample(range(LOW, HIGH), 2 * rng.randint(5, 12)))
    values, missing = pool[::2], pool[1::2]
    return _case("target absent #%d" % index, values, rng.choice(missing),
                 "The target falls between two elements, so the search must "
                 "finish empty-handed rather than run off the end.")


def _below_range(rng, index):
    values = _sorted_values(rng)
    return _case("below the range #%d" % index, values,
                 values[0] - rng.randint(1, 20))


def _above_range(rng, index):
    values = _sorted_values(rng)
    return _case("above the range #%d" % index, values,
                 values[-1] + rng.randint(1, 20))
